package dev.codex.lastzhelper;
import java.io.*;import java.util.*;import org.json.*;
/** Full eight-hour free collection; no early collect, purchases or jeep combat controls. */
final class ChestFeature implements MaintenanceFeature {
 public String id(){return "eight_hour_chest";}public int priority(){return 50;}
 public boolean permitsInput(String action,String path,boolean preview){if(action.equals("chest-preview"))return path.isEmpty();if(action.equals("chest-open"))return !preview&&path.isEmpty();return action.equals("ui-tap")&&(path.equals(ChestReader.VIEW+"close_btn")||path.equals("UIManagerInstance/windows/UIJeepAdventureMain/View/close_btn")||(!preview&&path.equals(ChestReader.VIEW+"receive_btn")));}
 public MaintenanceResult run(MaintenanceContext context)throws Exception{
  AutomationController c=context.controller;String pending=null;long attemptedSince=0;
  try{
   boolean route;try(GameMemory m=new GameMemory(c.cache)){route=ChestReader.routeOnly(m);}if(route)close(context,"UIJeepAdventureMain","UIManagerInstance/windows/UIJeepAdventureMain/View/close_btn",1);
   if(!c.open("UIStoryHangup")){
    long since,now;try(GameMemory m=new GameMemory(c.cache)){if(m.state.getInt("sceneId")!=1||m.state.getInt("modalWindowCount")!=0)throw new IOException("Chest requires base without dialogs");since=GameMemory.number(m.path("DataCenter/StoryManager"),"hangupTime");now=m.state.getLong("timestampMs");}
    JSONObject geometry=context.input.action(new JSONObject().put("action","chest-preview"));String text=geometry.optString("observedTime");if(ChestPolicy.partial(now,since,text))return result(MaintenanceResult.Outcome.NOTHING_TO_DO,"Eight-hour chest is accumulating",since+ChestPolicy.CAP_MS,geometry);
    if(!ChestPolicy.inspect(now,since,text,geometry.getJSONObject("collider").optBoolean("matches")).equals("FULL_INSPECTION_ONLY"))return result(MaintenanceResult.Outcome.BLOCKED,"Chest eligibility is not confirmed",0,geometry);
    if(context.preview)return result(MaintenanceResult.Outcome.PREVIEW,"Full chest inspected; no open or collect input",0,geometry);
    context.input.action(new JSONObject().put("action","chest-open").put("chestSince",since));c.waitWindow("UIStoryHangup",6000);
   }
   ChestReader reader=new ChestReader(context);JSONObject before=reader.read();long since=before.getLong("hangupTime"),now=System.currentTimeMillis();JSONObject button=before.getJSONObject("receive_btn");boolean eligible=ChestPolicy.claimable(now,since,before.getJSONObject("title_text").optString("text"),before.getJSONObject("time_text").optString("text"),before.getJSONObject("receive_text").optString("text"),button.getBoolean("active"),button.getBoolean("interactable"),before.getInt("rewardRows"));
   if(context.preview)return result(MaintenanceResult.Outcome.PREVIEW,"Idle reward inspected; full free claim eligible: "+eligible,0,before);
   if(!eligible)return result(MaintenanceResult.Outcome.BLOCKED,"Exact full free reward is not confirmed",0,before);
   attemptedSince=since;pending=context.begin(id(),ChestPolicy.period(since),"collect_full",before);context.active();context.input.action(new JSONObject().put("action","ui-tap").put("path",ChestReader.VIEW+"receive_btn").put("chestClaimSince",since));long until=System.currentTimeMillis()+12000;JSONObject after=null;
   while(System.currentTimeMillis()<until){context.input.pause(200);try(GameMemory m=new GameMemory(c.cache)){long changed=GameMemory.number(m.path("DataCenter/StoryManager"),"hangupTime");if(changed>since&&changed>=now-60000&&changed<=m.state.getLong("timestampMs")+2000&&!m.open("UIStoryHangup")){after=new JSONObject().put("hangupTime",changed).put("popupClosed",true).put("modalWindowCount",m.state.getInt("modalWindowCount")).put("knownRoute",ChestReader.routeOnly(m));break;}}}
   if(after==null)throw new IOException("Collection reset and popup close were not confirmed");context.store.verified(context.uid,pending,System.currentTimeMillis(),after);pending=null;
   return result((after.getInt("modalWindowCount")==0||after.optBoolean("knownRoute"))?MaintenanceResult.Outcome.COMPLETED:MaintenanceResult.Outcome.BLOCKED,"Eight-hour collection verified by game timestamp reset and popup close"+((after.getInt("modalWindowCount")==0||after.optBoolean("knownRoute"))?"":"; reward overlay needs inspection"),after.getLong("hangupTime")+ChestPolicy.CAP_MS,after);
  }catch(InterruptedException e){throw e;}catch(Exception e){if(pending!=null&&e instanceof DeviceInput.PreDispatchRejected){boolean unchanged;try(GameMemory m=new GameMemory(c.cache)){unchanged=GameMemory.number(m.path("DataCenter/StoryManager"),"hangupTime")==attemptedSince;}if(unchanged){JSONObject proof=new JSONObject().put("receipt",((DeviceInput.PreDispatchRejected)e).receipt).put("gameTimestampUnchanged",true);context.store.cancelBeforeInput(context.uid,pending,proof);pending=null;return result(MaintenanceResult.Outcome.BLOCKED,"Chest input rejected before dispatch; attempt preserved as cancelled, no automatic retry",System.currentTimeMillis()+900000,proof);}}
   if(pending!=null){context.store.uncertain(context.uid,pending,e.toString());return MaintenanceResult.of(MaintenanceResult.Outcome.UNCERTAIN,"Chest claim saved; no retry: "+e.getMessage(),0);}return MaintenanceResult.of(MaintenanceResult.Outcome.FAILED,"Chest stopped: "+e.getMessage(),System.currentTimeMillis()+900000);}
  finally{context.active();close(context,"UIStoryHangup",ChestReader.VIEW+"close_btn",1);close(context,"UIJeepAdventureMain","UIManagerInstance/windows/UIJeepAdventureMain/View/close_btn",1);}
 }
 void close(MaintenanceContext context,String window,String path,int modals)throws Exception{for(int attempt=0;attempt<3;attempt++){try(GameMemory m=new GameMemory(context.controller.cache)){if(!m.open(window)||m.state.getInt("modalWindowCount")!=modals)return;if(window.equals("UIJeepAdventureMain")&&!ChestReader.routeOnly(m))return;if(window.equals("UIStoryHangup")&&!ChestReader.knownWindows(m,true))return;}context.input.tapControl(path);long until=System.currentTimeMillis()+2000;while(context.controller.open(window)&&System.currentTimeMillis()<until)context.input.pause(150);}throw new IOException("Chest window did not close");}
 MaintenanceResult result(MaintenanceResult.Outcome outcome,String reason,long due,JSONObject snapshot){Map<String,String> evidence=new LinkedHashMap<>();evidence.put("snapshot",snapshot.toString());return new MaintenanceResult(outcome,reason,due,evidence);}
}
